// Build Airtable Project record from parsed onboarding data
const d = $input.first().json;

const briefParts = [
  d.product_feature ? `Product: ${d.product_feature}` : '',
  d.target_user ? `Target: ${d.target_user}` : '',
  d.biggest_problem ? `Problem: ${d.biggest_problem}` : '',
  d.differentiator ? `Differentiator: ${d.differentiator}` : '',
  d.main_hesitation ? `Hesitation: ${d.main_hesitation}` : '',
  d.selling_proposition ? `USP: ${d.selling_proposition}` : '',
  d.brand_personality ? `Personality: ${d.brand_personality}` : '',
  d.social_proof ? `Social proof: ${d.social_proof}` : '',
  d.competitors ? `Competitors: ${d.competitors}` : '',
  d.best_concepts ? `Concepts: ${d.best_concepts}` : '',
  d.do_not_say ? `Avoid: ${d.do_not_say}` : '',
  d.additional_notes ? `Notes: ${d.additional_notes}` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    records: [{
      fields: {
        client_code: d.client_code || '',
        brand_name: d.brand_name || '',
        client_name: d.client_name || '',
        client_email: d.client_email || '',
        num_scripts: d.num_scripts || 0,
        brief_summary: briefParts,
        status: 'Research'
      }
    }]
  }
}];

// ============================================================
// Error Handler — Capture error details
// ============================================================

const errorData = $input.first().json;

// Try to get brand name from the parse node if it ran
let brand_name = 'Unknown';
let client_code = 'N/A';
try {
  const parseData = $('Parse JotForm & Generate Client Code').first().json;
  brand_name = parseData.brand_name || 'Unknown';
  client_code = parseData.client_code || 'N/A';
} catch (e) {
  // Parse node may not have run
}

const errorMessage = errorData.error?.message || errorData.message || 'Unknown error';
const errorNode = errorData.error?.node?.name || errorData.node || 'Unknown node';

return [{
  json: {
    brand_name,
    client_code,
    error_message: errorMessage,
    error_node: errorNode,
    created_at: new Date().toISOString()
  }
}];

// ============================================================
// TEST DATA — Simulates a raw JotForm webhook submission
// Outputs data in the same format JotForm sends, so it flows
// through the Parse node and all downstream references work.
// Edit these values to test with different brands.
// ============================================================

return [{
  json: {
    body: {
      client_name: 'Test User',
      client_email: 'test@example.com',
      whatsapp_number: '+919999999999',
      brand_name: 'TestBrand',
      website_url: 'https://testbrand.com',
      product_feature: 'Premium organic skincare serum with Vitamin C',
      differentiator: 'Only brand using high-altitude Himalayan botanicals',
      competitors: 'Mamaearth, Plum, Minimalist',
      competitor_strengths: 'Mamaearth has strong distribution, Minimalist has science-forward branding',
      target_user: 'Women 22-35, urban, ingredient-conscious, mid-premium budget',
      biggest_problem: 'Dull skin, dark spots, want visible results in 2 weeks',
      main_hesitation: 'Too many serums in the market — why is this different?',
      social_proof: '15K+ 5-star reviews, featured in Vogue India',
      selling_proposition: 'Visible glow in 14 days or money back',
      brand_personality: 'Clean, confident, earthy-luxe, approachable expert',
      credibility_point: 'Dermatologist-tested, certified organic ingredients',
      transformation: 'From dull tired skin to lit-from-within glow',
      best_concepts: 'Before/after, ingredient hero, routine integration',
      compliance: 'No medical claims, no before/after showing skin disease',
      reference_ads: 'Minimalist serum ads, Drunk Elephant UGC style',
      available_assets: 'Product photos, ingredient cards, customer testimonials',
      do_not_say: 'Do not say anti-aging, do not compare directly to competitors by name',
      num_scripts: 6,
      additional_notes: 'Client prefers warm lighting in all UGC. Launch date is March 15.'
    }
  }
}];

// ============================================================
// Generate Script Doc Names for Google Drive
// Creates N doc entries matching the ClickUp card names
// ============================================================

const d = $('Parse JotForm & Generate Client Code').first().json;
const scriptsFolderId = $('Create Scripts Subfolder').first().json.id;
const count = d.num_scripts || 0;

if (count === 0) return [{ json: { _skip: true, scriptsFolderId } }];

const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const now = new Date();
const monYear = months[now.getMonth()] + "'" + String(now.getFullYear()).slice(-2);

const docs = [];
for (let i = 1; i <= count; i++) {
  docs.push({
    name: `UGC_C${i}_${d.brand_name}_Creator Name_R1_${monYear}`,
    scriptsFolderId
  });
}

return docs.map(d => ({ json: d }));

// ============================================================
// Build Brand record payload for Airtable upsert
// Uses fieldsToMergeOn to avoid duplicates
// ============================================================
const d = $('Parse JotForm & Generate Client Code').first().json;

// Build brand fields from onboarding data
const fields = {
  brand_name: d.brand_name,
  primary_contact: d.client_name || '',
  contact_email: d.client_email || '',
  whatsapp: d.whatsapp_number || '',
  website_url: d.website_url || '',
  status: 'Active',
  onboarded_date: new Date().toISOString().split('T')[0]
};

// Try to get Drive folder ID if available
try {
  const driveFolder = $('Create Brand Folder in Drive').first().json;
  if (driveFolder && driveFolder.id) {
    fields.drive_folder_id = driveFolder.id;
  }
} catch(e) {}

// Try to get ClickUp list ID if available
try {
  const clickupList = $('Create Pipeline List in Folder').first().json;
  if (clickupList && clickupList.id) {
    fields.clickup_list_id = clickupList.id;
  }
} catch(e) {}

return [{ json: {
  body: {
    performUpsert: { fieldsToMergeOn: ['brand_name'] },
    records: [{ fields }]
  }
} }];

// ============================================================
// Prep Creator Scout Request — auto-trigger after onboarding
// Reads parsed onboarding data and maps to Creator Scout input
// ============================================================
const projectData = $('Parse JotForm & Generate Client Code').first().json;

const brand_name = projectData.brand_name || '';
const industry = (projectData.product_feature || '').toLowerCase();
const num_scripts = projectData.num_scripts || 5;

// Map industry keywords to niches
const nicheMap = {
  'skincare': ['Beauty'], 'beauty': ['Beauty'], 'wellness': ['Health'],
  'fashion': ['Fashion'], 'fitness': ['Fitness'], 'finance': ['Finance'],
  'fintech': ['Finance'], 'food': ['Food'], 'tech': ['Tech'],
  'lifestyle': ['Lifestyle'], 'travel': ['Travel'], 'auto': ['Auto'],
  'education': ['Education'], 'gaming': ['Gaming'],
  'health': ['Health'], 'cosmetic': ['Beauty'], 'makeup': ['Beauty'],
  'clothing': ['Fashion'], 'apparel': ['Fashion'], 'gym': ['Fitness'],
  'sports': ['Fitness'], 'banking': ['Finance'], 'investment': ['Finance'],
  'restaurant': ['Food'], 'beverage': ['Food'], 'drink': ['Food'],
  'software': ['Tech'], 'app': ['Tech'], 'saas': ['Tech'],
  'hotel': ['Travel'], 'tourism': ['Travel'], 'car': ['Auto'],
  'vehicle': ['Auto'], 'learning': ['Education'], 'course': ['Education']
};

let niches = [];
for (const [key, val] of Object.entries(nicheMap)) {
  if (industry.includes(key)) {
    for (const v of val) {
      if (!niches.includes(v)) niches.push(v);
    }
  }
}
if (niches.length === 0) niches = ['UGC']; // fallback

return [{ json: {
  scout_request: {
    niches: niches,
    budget_max: 5000,
    count: Math.max(num_scripts, 3),
    brand_name: brand_name,
    location: 'India',
    languages: ['English', 'Hindi'],
    source: 'onboarding_auto_scout'
  }
}}];

// ============================================================
// Parse JotForm & Generate Client Code
// Handles multiple JotForm data formats
// ============================================================

const body = $input.first().json.body || $input.first().json;

// --- STRATEGY 1: rawRequest JSON string ---
let parsed = null;
try {
  if (body.rawRequest && typeof body.rawRequest === 'string') {
    parsed = JSON.parse(body.rawRequest);
  } else if (body.rawRequest && typeof body.rawRequest === 'object') {
    parsed = body.rawRequest;
  }
} catch (e) {
  parsed = null;
}

// --- STRATEGY 2: q-prefixed fields (q1_whatIs, q2_email, etc.) ---
function fromQFields(b) {
  const qMap = {};
  for (const key of Object.keys(b)) {
    if (/^q\d+/.test(key)) {
      qMap[key] = b[key];
    }
  }
  if (Object.keys(qMap).length === 0) return null;

  // Sort by question number
  const sorted = Object.entries(qMap).sort((a, b) => {
    const numA = parseInt(a[0].match(/^q(\d+)/)[1]);
    const numB = parseInt(b[0].match(/^q(\d+)/)[1]);
    return numA - numB;
  });

  // Map by order (best-effort mapping based on form field order)
  const fieldOrder = [
    'client_name', 'client_email', 'whatsapp_number', 'brand_name', 'website_url',
    'product_feature', 'differentiator', 'competitors', 'competitor_strengths',
    'target_user', 'biggest_problem', 'main_hesitation',
    'social_proof', 'selling_proposition', 'brand_personality', 'credibility_point', 'transformation',
    'best_concepts', 'compliance', 'reference_ads', 'available_assets', 'do_not_say', 'additional_notes', 'num_scripts'
  ];

  const result = {};
  sorted.forEach(([key, val], i) => {
    if (i < fieldOrder.length) {
      result[fieldOrder[i]] = val;
    }
  });
  return result;
}

// --- STRATEGY 3: Direct field names ---
function fromDirectFields(b) {
  const directFields = [
    'client_name', 'client_email', 'whatsapp_number', 'brand_name', 'website_url',
    'product_feature', 'differentiator', 'competitors', 'competitor_strengths',
    'target_user', 'biggest_problem', 'main_hesitation',
    'social_proof', 'selling_proposition', 'brand_personality', 'credibility_point', 'transformation',
    'best_concepts', 'compliance', 'reference_ads', 'available_assets', 'do_not_say', 'additional_notes', 'num_scripts'
  ];
  const found = {};
  let count = 0;
  for (const f of directFields) {
    if (b[f] !== undefined) {
      found[f] = b[f];
      count++;
    }
  }
  return count > 0 ? found : null;
}

// Resolve data source
let data = parsed || fromQFields(body) || fromDirectFields(body) || body;

// --- HELPER: Clean a field value ---
function clean(val) {
  if (val === undefined || val === null) return '';
  if (Array.isArray(val)) return val.map(v => String(v).trim()).filter(Boolean).join(', ');
  if (typeof val === 'object') {
    // Handle name object: { first, last } or { prefix, first, middle, last }
    if (val.first || val.last) {
      return [val.prefix, val.first, val.middle, val.last].filter(Boolean).map(s => String(s).trim()).join(' ');
    }
    // Handle phone object: { area, phone } or { countryCode, area, phone }
    if (val.phone !== undefined) {
      const parts = [val.countryCode, val.area, val.phone].filter(Boolean).map(s => String(s).replace(/[\s\-()]/g, ''));
      return parts.join('');
    }
    return JSON.stringify(val);
  }
  return String(val).trim();
}

// --- Extract and clean all 23 fields ---
const client_name = clean(data.client_name || data.clientName || data.name);
const client_email = clean(data.client_email || data.clientEmail || data.email);
const whatsapp_number = clean(data.whatsapp_number || data.whatsappNumber || data.whatsapp || data.phone);
